public event Action<string> Line;
// Only same-process live OS WAL receipts establish Connected/Stopped.
volatile bool nativeApplied, nativeStopped;
public bool Active

nativeApplied = nativeStopped = false;
process = new Process { StartInfo = Info("--native-v4-product --control-stdin --config " + Quote(config)), EnableRaisingEvents = true };
process.OutputDataReceived += (s, e) => {
    if (e.Data == null) return;
    if (e.Data == "WBD_WINDOWS_OS_APPLIED") nativeApplied = true;
    if (e.Data == "WBD_WINDOWS_NATIVE_DISCONNECTED_V1 wal_restored=1 rust_stopped=1") nativeStopped = true;
    if (Line != null) Line(e.Data);
};

if (process.ExitCode != 0)
    throw new IOException("原始客户端异常退出；不能宣称驱动或 owned 网络已经清理。");
if (nativeApplied && !nativeStopped)
    throw new IOException("已 Applied 的原生 Windows 网络缺少真实 WAL CAS/Rust Stop 回执，拒绝显示已断开。");
